function Icon({name}){const p={search:<><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></>,pin:<><path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></>,calendar:<><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/></>,heart:<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8l8.9 8.6 8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>,arrow:<><path d="M5 12h14M13 6l6 6-6 6"/></>,close:<><path d="M6 6l12 12M18 6 6 18"/></>,menu:<><path d="M4 7h16M4 12h16M4 17h16"/></>};return <svg viewBox="0 0 24 24" aria-hidden="true">{p[name]}</svg>}
function Card({item,open,saved,save}){const city=cities.find(c=>c.id===item.city);return <article className="listing-card" onClick={()=>open(item)}><div className="listing-image"><img src={item.image} alt="" loading="lazy" onError={e=>e.currentTarget.src=shot}/><span className="type-pill">{item.subtype}</span><button className={saved?"save active":"save"} onClick={e=>{e.stopPropagation();save(item.id)}}><Icon name="heart"/></button></div><div className="listing-copy"><small>{city?.name}</small><h3>{item.title}</h3><p>{item.description}</p><div className="listing-meta"><span><Icon name={item.date?"calendar":"pin"}/>{item.date||item.place}</span><b>View <Icon name="arrow"/></b></div></div></article>}
function Header({page,setPage,search,saved}){const[open,setOpen]=useState(false);return <header className="topbar"><button className="brand" onClick={()=>setPage("Discover")}><img src={logo}/><span>KosovaGo</span></button><nav className={open?"open":""}>{nav.map(n=><button key={n} className={page===n?"active":""} onClick={()=>{setPage(n);setOpen(false)}}>{n}</button>)}</nav><div className="top-actions"><button className="search-btn" onClick={search}><Icon name="search"/><span>Search</span></button><span className="saved-chip">♡ {saved}</span><button className="hamburger" onClick={()=>setOpen(!open)}><Icon name={open?"close":"menu"}/></button></div></header>}
function SectionTitle({icon="✣",title,action,onAction}){return <div className="section-title"><div><span>{icon}</span><h2>{title}</h2></div>{action&&<button onClick={onAction}>{action}<Icon name="arrow"/></button>}</div>}
function Home({setPage,setCity,open,saved,save,search}){return <><section className="home-hero"><div className="home-copy"><span>Welcome to</span><h1>Kosovo</h1><p>Discover the heart of the Balkans</p><div><button className="gold-button" onClick={()=>setPage("Cities")}>Explore cities <Icon name="arrow"/></button><button className="ghost-button" onClick={search}><Icon name="search"/>Search everything</button></div></div><div className="app-preview"><img src={shot}/><b>Your app. Now useful on the web too.</b></div></section><section className="content-section"><SectionTitle title="Featured Events" action="See all" onAction={()=>setPage("Events")}/><div className="featured-grid">{items.filter(x=>x.type==="Events").slice(0,3).map(i=><Card key={i.id} item={i} open={open} saved={saved.includes(i.id)} save={save}/>)}</div></section><section className="content-section"><SectionTitle icon="⌖" title="Explore the Cities" action="All cities" onAction={()=>setPage("Cities")}/><div className="city-grid">{cities.slice(0,8).map(c=><button className="city-card" key={c.id} onClick={()=>setCity(c)}><img src={photos[c.id]} onError={e=>e.currentTarget.src=shot}/><div><h3>{c.name}</h3><p>{c.region}</p><span>Open guide <Icon name="arrow"/></span></div></button>)}</div></section><section className="category-band">{["Food","Nightlife","Culture","Activities","Cinemas"].map((x,i)=><button key={x} onClick={()=>setPage(x)}><span>0{i+1}</span><h3>{x}</h3><p>{meta[x][1]}</p><b>Browse <Icon name="arrow"/></b></button>)}</section></>}
function PageHero({page}){const m=meta[page]||["Discover Kosovo","Real places and useful local picks."];return <section className="page-hero"><span>KosovaGo guide</span><h1>{m[0]}</h1><p>{m[1]}</p></section>}
function Browse({page,setCity,open,saved,save}){const[filter,setFilter]=useState("all");const data=useMemo(()=>allItems.filter(x=>x.type===page&&(filter==="all"||x.city===filter)),[page,filter]);if(page==="Cities")return <><PageHero page={page}/><section className="content-section"><div className="all-city-grid">{cities.map(c=><button className="city-guide" onClick={()=>setCity(c)} key={c.id}><img src={photos[c.id]} onError={e=>e.currentTarget.src=shot}/><div><span>{c.region}</span><h2>{c.name}</h2><p>{c.intro}</p><b>Open city guide <Icon name="arrow"/></b></div></button>)}</div></section></>;return <><PageHero page={page}/><section className="content-section"><div className="filter-row"><button className={filter==="all"?"active":""} onClick={()=>setFilter("all")}>All Kosovo</button>{cities.map(c=><button key={c.id} className={filter===c.id?"active":""} onClick={()=>setFilter(c.id)}>{c.name}</button>)}</div>{data.length?<div className="listing-grid">{data.map(i=><Card key={i.id} item={i} open={open} saved={saved.includes(i.id)} save={save}/>)}</div>:<div className="empty-state"><h2>More verified listings are being added.</h2><p>No made-up filler just to make the grid look busy.</p></div>}</section></>}
function City({city,back,open,saved,save}){const data=allItems.filter(x=>x.city===city.id);return <><section className="city-hero"><img src={photos[city.id]}/><div><button onClick={back}>← All cities</button><span>{city.region}</span><h1>{city.name}</h1><p>{city.intro}</p></div></section><section className="content-section"><div className="city-highlights">{city.highlights.map((x,i)=><div key={x}><span>0{i+1}</span><b>{x}</b></div>)}</div><SectionTitle title={"Explore "+city.name}/>{data.length?<div className="listing-grid">{data.map(i=><Card key={i.id} item={i} open={open} saved={saved.includes(i.id)} save={save}/>)}</div>:<div className="empty-state"><h2>Detailed listings are being verified.</h2><p>The city essentials above are live.</p></div>}</section></>}
function Search({close,open}){const[q,setQ]=useState("");const r=q.length<2?[]:allItems.filter(x=>(x.title+" "+x.description+" "+x.type+" "+x.place).toLowerCase().includes(q.toLowerCase())).slice(0,10);return <div className="modal-backdrop" onMouseDown={close}><div className="search-modal" onMouseDown={e=>e.stopPropagation()}><div className="search-box"><Icon name="search"/><input autoFocus placeholder="Search events, restaurants, museums…" value={q} onChange={e=>setQ(e.target.value)}/><button onClick={close}><Icon name="close"/></button></div><div className="search-results">{q.length<2?<p>Try “museum”, “Prizren”, “concert” or “Rugova”.</p>:r.length?r.map(x=><button key={x.id} onClick={()=>{close();open(x)}}><img src={x.image}/><span><small>{x.type} · {cities.find(c=>c.id===x.city)?.name}</small><b>{x.title}</b><em>{x.place}</em></span><Icon name="arrow"/></button>):<p>No match yet. Try another place or category.</p>}</div></div></div>}
function Detail({item,close,saved,save}){const c=cities.find(x=>x.id===item.city),maps="https://www.google.com/maps/search/?api=1&query="+encodeURIComponent(item.title+" "+c?.name);return <div className="modal-backdrop detail-backdrop" onMouseDown={close}><article className="detail-modal" onMouseDown={e=>e.stopPropagation()}><button className="detail-close" onClick={close}><Icon name="close"/></button><img className="detail-image" src={item.image}/><div className="detail-content"><span className="type-pill">{item.subtype}</span><small>{c?.name} · {item.type}</small><h2>{item.title}</h2><p>{item.description}</p>{item.date&&<div className="detail-line"><Icon name="calendar"/><span><b>{item.date}</b><small>{item.place}</small></span></div>}<div className="detail-actions"><a href={maps} target="_blank">Open in Maps <Icon name="arrow"/></a>{item.link&&<a className="secondary" href={item.link} target="_blank">Official programme</a>}<button className={saved?"active":""} onClick={()=>save(item.id)}><Icon name="heart"/>{saved?"Saved":"Save"}</button></div><p className="accuracy-note">Programmes and opening times can change. Check the venue or organiser before travelling.</p></div></article></div>}
export default function App(){const[page,setP]=useState("Discover"),[city,setC]=useState(null),[detail,setDetail]=useState(null),[search,setSearch]=useState(false),[saved,setSaved]=useState(()=>{try{return JSON.parse(localStorage.getItem("kg-saved"))||[]}catch{return[]}});const setPage=p=>{setP(p);setC(null);scrollTo(0,0);location.hash=p.toLowerCase()},setCity=c=>{setC(c);scrollTo(0,0);location.hash="city/"+c.id},save=id=>setSaved(s=>s.includes(id)?s.filter(x=>x!==id):[...s,id]);useEffect(()=>localStorage.setItem("kg-saved",JSON.stringify(saved)),[saved]);return <div className="app-shell"><Header page={page} setPage={setPage} search={()=>setSearch(true)} saved={saved.length}/><main>{city?<City city={city} back={()=>setPage("Cities")} open={setDetail} saved={saved} save={save}/>:page==="Discover"?<Home setPage={setPage} setCity={setCity} open={setDetail} saved={saved} save={save} search={()=>setSearch(true)}/>:<Browse page={page} setCity={setCity} open={setDetail} saved={saved} save={save}/>}</main><footer><button className="brand" onClick={()=>setPage("Discover")}><img src={logo}/><span>KosovaGo</span></button><p>Discover the heart of the Balkans.</p><div><a href="/privacy.html">Privacy</a><a href="mailto:gokosova@outlook.com">Contact</a><span>© {new Date().getFullYear()}</span></div></footer>{search&&<Search close={()=>setSearch(false)} open={setDetail}/>} {detail&&<Detail item={detail} close={()=>setDetail(null)} saved={saved.includes(detail.id)} save={save}/>}</div>}
